'use strict';
const collections = [
 {name:'Jewelry & luxury retailers',group:'retail',description:'Independent stores, designer boutiques and luxury retail buyers.',buyers:'Jewelry brands, wholesalers, sales representatives and retail-service providers.',fields:['Brands carried','Retail positioning','Bridal vs. fashion focus','Buying role'],icon:'M12 3 3 9l9 12 9-12-9-6ZM3 9h18M8 9l4 12 4-12M8 9l4-6 4 6'},
 {name:'Property managers',group:'services',description:'Multifamily operators and commercial property-management firms.',buyers:'HVAC, roofing, landscaping, restoration, security and property-technology companies.',fields:['Property types','Portfolio geography','Published unit count','Management role'],icon:'M4 21V5h10v16M14 10h6v11M2 21h20M8 9h2M8 13h2M8 17h2M17 14h1M17 18h1'},
 {name:'Home-service contractors',group:'services',description:'HVAC, plumbing, roofing and electrical businesses by service area.',buyers:'Equipment distributors, trade software, insurers and specialized marketing firms.',fields:['Trade specialty','Service area','Public license details','Residential vs. commercial'],icon:'m3 11 9-8 9 8M5 10v11h14V10M9 21v-7h6v7'},
 {name:'Dental practices',group:'health',description:'Independent practices, specialists and multi-location dental groups.',buyers:'Dental labs, equipment suppliers, practice software and staffing companies.',fields:['Practice specialty','Provider count','Independent vs. group','Location count'],icon:'M8 3C3 3 3 8 5 12c1 2 0 8 3 9 2 0 1-7 4-7s2 7 4 7c3-1 2-7 3-9 2-4 2-9-3-9-2 0-2 2-4 2S10 3 8 3Z'},
 {name:'Med spas & aesthetics',group:'health',description:'Medical spas, dermatology practices and aesthetic clinics.',buyers:'Skincare brands, device suppliers, booking platforms and professional training companies.',fields:['Treatments offered','Publicly listed devices','Provider roles','Location count'],icon:'M12 3v18M3 12h18M6 6l12 12M6 18 18 6'},
 {name:'Restaurants & hotels',group:'retail',description:'Hospitality operators, independent venues and announced openings.',buyers:'Food distributors, POS providers, furniture suppliers, linen services and staffing firms.',fields:['Venue concept','Announced opening date','Operator or group','Published capacity'],icon:'M4 3v6c0 3 6 3 6 0V3M7 3v18M18 3c-4 4-4 10 0 10V3Zm0 10v8'},
 {name:'Commercial construction',group:'industrial',description:'Commercial contractors and publicly announced project opportunities.',buyers:'Material suppliers, subcontractors, equipment-rental firms and construction-service providers.',fields:['Project type','Public permit date','Project stage','Named project participants'],icon:'M3 21h18M5 21V3h4v18M9 5h12l-6-3H5M18 5v8M16 13h4v3h-4Z'},
 {name:'Auto repair & collision',group:'services',description:'Independent repair shops, collision centers and tire businesses.',buyers:'Parts distributors, shop-management platforms and diagnostic-equipment suppliers.',fields:['Shop specialty','Certifications','Vehicle specialties','Location count'],icon:'m4 10 2-6h12l2 6M3 10h18v8H3ZM5 18v3M19 18v3M6 14h2M16 14h2'},
 {name:'Law firms',group:'services',description:'Law practices segmented by specialty, geography and firm profile.',buyers:'Legal-tech vendors, litigation-support providers, recruiters and specialist agencies.',fields:['Practice areas','Public attorney count','Office locations','Leadership roles'],icon:'M12 3v18M5 21h14M3 7h18M6 7l-3 7h6L6 7Zm12 0-3 7h6l-3-7'},
 {name:'E-commerce brands',group:'retail',description:'Online brands organized by product category and store characteristics.',buyers:'3PLs, packaging suppliers, e-commerce agencies, payment services and software vendors.',fields:['Product category','Observable store platform','Retail price range','Shipping regions'],icon:'M4 8h16l1 13H3L4 8Zm4 0V6a4 4 0 0 1 8 0v2'}
, ...additionalCollections
];
const tiers={Essential:{price:249,count:'Up to 100 businesses',scope:'One industry / one US state'},Intelligence:{price:749,count:'Up to 300 businesses',scope:'One industry / up to three US states'},Bespoke:{price:1500,count:'Count to be scoped',scope:'Custom territory and criteria'}};
const catalogPage=document.body.dataset.page==='catalog';
const grid=document.querySelector('#collection-grid'),modal=document.querySelector('#modal'),content=document.querySelector('#modal-content');
let activeFilter='all',lastFocus=null,toastTimer;
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
const escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function renderCollections(){
 const query=(document.querySelector('#search')?.value||'').trim().toLowerCase();
 const matches=collections.map((c,index)=>({...c,index})).filter(c=>!catalogPage?[0,2,25].includes(c.index):(activeFilter==='all'||(activeFilter==='business'&&!isConsumer(c))||c.group===activeFilter)&&`${c.name} ${c.description} ${c.buyers} ${c.fields.join(' ')}`.toLowerCase().includes(query));
 grid.innerHTML=matches.map(c=>`<article class="collection-card ${c.index===0?'first':''}"><div class="collection-card-top"><span class="industry-icon"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="${c.icon||categoryIcons[c.group]}"/></svg></span><span class="collection-kind ${isConsumer(c)?'consumer-kind':''}">${isConsumer(c)?'CONSUMER MARKET':'BUSINESS LIST'}</span></div><h3>${c.name}</h3><p>${c.description}</p><div class="recommended"><span>Recommended for</span><p>${c.buyers}</p></div><div class="collection-card-bottom"><span>From <strong>$249</strong> / project</span><button data-detail="${c.index}" aria-label="Explore ${c.name}">Explore ${isConsumer(c)?'profile':'list'} ↗</button></div></article>`).join('');
 const count=document.querySelector('#result-count');if(count)count.textContent=catalogPage?`${matches.length} of 30 collections · US-focused · Pre-launch catalog`:'3 featured collections · 30 ways to find your market';
 const empty=document.querySelector('#empty');if(empty)empty.hidden=matches.length>0;
}
function showModal(label,html){if(!modal.open)lastFocus=document.activeElement;document.querySelector('#modal-label').textContent=label;content.innerHTML=html;if(!modal.open)modal.showModal();modal.scrollTop=0;document.body.style.overflow='hidden';modal.querySelector('.close').focus();}
modal.querySelector('.close').addEventListener('click',()=>modal.close());modal.addEventListener('close',()=>{document.body.style.overflow='';lastFocus?.focus();});modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close();}});
function validIndex(index){const n=Number(index);if(!Number.isInteger(n)||n<0||n>=collections.length)throw Error('Unknown collection');return n;}
function detail(index){
 index=validIndex(index);const c=collections[index],geo=isConsumer(c);
 showModal(geo?'CONSUMER MARKET / AREA-LEVEL RESEARCH':'BUSINESS COLLECTION',`<h2 id="modal-title">${c.name}</h2><p>${c.description}</p><div class="detail-recommended"><h3 class="modal-subtitle">Recommended for</h3><p>${c.buyers}</p></div><h3 class="modal-subtitle">${geo?'Market indicators':'Industry-specific research fields'}</h3><div class="modal-fields">${c.fields.map(f=>`<span class="field-chip">${f}</span>`).join('')}</div><p><strong>${geo?'One record per geographic area.':'One record per business.'}</strong> Core fields: ${(geo?coreConsumer:coreBusiness).join(', ')}.</p>${geo?'<p>Source approach: published Census / ACS estimates, subject to coverage and data quality. Estimates include their vintage and uncertainty. An area median does not describe any individual household.</p><p class="notice">Aggregate market planning only. No consumer names, street addresses, emails, phone numbers or individual income estimates are included.</p>':'<p class="notice">Pre-launch collection. Contact and field coverage depend on source availability and the selected package. No actual list is available for immediate download.</p>'}<div class="modal-package-row">Essential $249 · Intelligence $749 · Bespoke $1,500+<small>${geo?'Targets: up to 25 areas / up to 100 areas / custom scope.':'Targets: up to 100 businesses / up to 300 businesses / custom scope.'} Proposed pricing; final scope requires confirmation.</small></div><div class="modal-actions"><button class="button dark" data-build data-index="${index}">Build this ${geo?'market':'list'} brief ↗</button><button class="button bordered" data-sample="${index}">View sample fields</button></div>`);
}
function sample(index){
 index=validIndex(index);const c=collections[index],geo=isConsumer(c);
 showModal('SAMPLE STRUCTURE',`<h2 id="modal-title">${c.name}</h2><p>Preview the proposed file structure before choosing your research scope.</p><div class="notice">Illustrative sample only. This file contains ${geo?'one fictional geographic area, with no real statistics or personal contacts':'one fictional company—not a verified business or opted-in lead'}.</div><h3 class="modal-subtitle">Core fields</h3><div class="modal-fields">${(geo?coreConsumer:coreBusiness).map(f=>`<span class="field-chip">${f}</span>`).join('')}</div><h3 class="modal-subtitle">${geo?'Market indicators':'Optional industry fields'}</h3><div class="modal-fields">${c.fields.map(f=>`<span class="field-chip">${f}</span>`).join('')}</div><div class="modal-actions"><button class="button dark" data-download="${index}">Download sample CSV ↓</button><button class="button bordered" data-build data-index="${index}">Build a brief ↗</button></div>`);
}
function toast(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('visible'),4500);}
function download(name,data,type){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('Download prepared. Check your browser downloads.');}
function sampleCsv(index){
 const c=collections[validIndex(index)],geo=isConsumer(c);
 const headers=[...(geo?coreConsumer:coreBusiness),...c.fields,'Record status'];
 const base=geo?['FICTIONAL EXAMPLE AREA','Census tract','EXAMPLE — NOT A REAL ID','Example state','https://www.census.gov/','Not researched','Illustrative only']:['FICTIONAL EXAMPLE — NOT A PROSPECT','https://example.com','sample@example.com','','Example city','Example state','https://example.com',''];
 const row=[...base,...c.fields.map(()=> 'Illustrative field — not researched'),'FICTIONAL SAMPLE'];
 return '\uFEFF'+[headers,row].map(r=>r.map(v=>'"'+v.replaceAll('"','""')+'"').join(',')).join('\r\n');
}
function packageSummary(index,tier){
 const c=collections[validIndex(index)];if(!Object.hasOwn(tiers,tier))throw Error('Unknown package');
 const t=tiers[tier];const areas={Essential:'Up to 25 areas',Intelligence:'Up to 100 areas',Bespoke:'Area count to be scoped'};
 return {price:t.price,count:isConsumer(c)?areas[tier]:t.count,scope:t.scope.replace('industry','collection'),kind:isConsumer(c)?'Aggregate consumer-market research':'Business-list research'};
}
function briefText(values){
 const index=validIndex(values.industry),c=collections[index],geo=isConsumer(c),p=packageSummary(index,values.tier);
 const territory=String(values.territory||'').trim(),criteria=String(values.criteria||'').trim();
 if(!territory||!criteria)throw Error('Please enter a territory and research priorities.');
 const geography=['County','City / place','Census tract','ZIP Code Tabulation Area (ZCTA)'].includes(values.geography)?values.geography:'To be scoped';
 const income=['No income threshold','$75,000+','$100,000+','$150,000+','$200,000+'].includes(values.income)?values.income:'No income threshold';
 return `REACHVENTORY — RESEARCH PROJECT BRIEF\nPrepared: ${new Date().toISOString().slice(0,10)}\nStatus: DRAFT / NOT SUBMITTED / NOT AN ORDER\n\nProject: ${String(values.company||'').trim()||'Untitled project'}\nCollection: ${c.name}\nType: ${p.kind}\nRecommended for: ${c.buyers}\nPackage: ${values.tier}\nProposed starting price: ${money(p.price)} USD${values.tier==='Bespoke'?' and up':''}\nTarget coverage: ${p.count}\nPackage scope: ${p.scope}\nRequested territory: ${territory}\n${geo?`Geography: ${geography}\n${index===25?`Requested AREA median income filter: ${income}\n`:''}Area-level estimates only. No individual income or personal contacts.\n`:''}\nIDEAL AUDIENCE & RESEARCH PRIORITIES\n${criteria}\n\nCORE FIELDS\n${(geo?coreConsumer:coreBusiness).join(', ')}\n\nSPECIALIST FIELDS TO SCOPE\n${c.fields.join(', ')}\n\nIMPORTANT\nThis file was generated locally in your browser. It has not been sent to Reachventory. Lists and checkout are not yet available. Final scope, field coverage, count, pricing and delivery timing must be confirmed before purchase. No contact coverage, consent, response rate or sales outcome is guaranteed.${geo?' Census/ACS values are estimates for geographic areas, not information about individuals. Use geography identifiers, dataset vintage and margins of error. ZCTAs are statistical areas and do not exactly equal postal ZIP codes. Do not use area profiles to determine individual eligibility for credit, housing, employment or insurance.':''}\n`;
}
function downloadSample(index){index=validIndex(index);download('reachventory-'+collections[index].name.toLowerCase().replace(/[^a-z0-9]+/g,'-')+'-sample.csv',sampleCsv(index),'text/csv;charset=utf-8');}
function build(index=0,tier='Intelligence'){
 index=validIndex(index);packageSummary(index,tier);
 showModal('YOUR NEXT MARKET, DEFINED',`<h2 id="modal-title">Build your research brief.</h2><p>Choose your audience and download a shareable project outline. Nothing is submitted or ordered.</p><form id="brief-form"><div class="form-grid"><label class="form-label">Collection<select name="industry">${collections.map((c,i)=>`<option value="${i}" ${i===index?'selected':''}>${c.name}</option>`).join('')}</select></label><label class="form-label">Package<select name="tier">${Object.keys(tiers).map(t=>`<option ${t===tier?'selected':''}>${t}</option>`).join('')}</select></label><label class="form-label full">Target territory<input name="territory" required maxlength="180" placeholder="e.g. New York, New Jersey and Connecticut"></label><label class="form-label full" id="geography-field" hidden>Geographic unit<select name="geography"><option>County</option><option>City / place</option><option>Census tract</option><option>ZIP Code Tabulation Area (ZCTA)</option></select></label><label class="form-label full" id="income-field" hidden>Area median household income target<select name="income"><option>No income threshold</option><option>$75,000+</option><option>$100,000+</option><option>$150,000+</option><option>$200,000+</option></select><small>Applies to the area median—not individual income. Estimate availability varies.</small></label><label class="form-label full"><span id="criteria-label">Ideal customer & research priorities</span><textarea name="criteria" required maxlength="2000" placeholder="Describe the audience, qualifications and exclusions you need."></textarea></label><label class="form-label full">Your company or project name (optional)<input name="company" maxlength="150" placeholder="Name this research project"></label></div><div class="brief-total"><div><span>Proposed starting price · USD</span><p id="brief-scope"></p></div><strong id="brief-price"></strong></div><p class="notice" id="brief-notice"></p><div class="modal-actions"><button class="button dark" type="submit">Download my brief ↓</button></div></form>`);
 const form=document.querySelector('#brief-form');
 const update=()=>{
  const i=Number(form.elements.industry.value),geo=isConsumer(collections[i]),p=packageSummary(i,form.elements.tier.value);
  document.querySelector('#brief-price').textContent=money(p.price)+(form.elements.tier.value==='Bespoke'?'+':'');
  document.querySelector('#brief-scope').textContent=p.count+' · '+p.scope;
  document.querySelector('#geography-field').hidden=!geo;form.elements.geography.disabled=!geo;
  document.querySelector('#income-field').hidden=i!==25;form.elements.income.disabled=i!==25;
  document.querySelector('#criteria-label').textContent=geo?'Market-planning goals & area selection criteria':'Ideal customer & research priorities';
  document.querySelector('#brief-notice').textContent=(geo?'Area-level market profiles only; no personal contacts or individual income. ':'')+'Pre-launch planning only. Exporting a brief does not send an inquiry, reserve data or charge you. Entries are not stored by this form.';
 };
 form.elements.tier.addEventListener('change',update);form.elements.industry.addEventListener('change',update);update();
 form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;try{download('reachventory-research-brief.txt',briefText(Object.fromEntries(new FormData(form))),'text/plain;charset=utf-8');}catch(error){toast(error.message);}});
}
function policy(){showModal('PRIVACY & LAUNCH INFORMATION',`<h2 id="modal-title">A transparent starting point.</h2><h3 class="modal-subtitle">Pre-launch catalog</h3><p>Reachventory is a working brand. Packages and prices are proposed. No real datasets are being sold, no payments are collected, and exporting a brief does not place an order or contact a sales team.</p><h3 class="modal-subtitle">Consumer-market profiles</h3><p>Consumer collections describe geographic areas using aggregate statistics. They contain no personal contacts or individual income. Do not use area profiles to determine individual eligibility for credit, housing, employment or insurance.</p><h3 class="modal-subtitle">Information entered here</h3><p>The brief builder generates a file in your browser. Its entries are not sent to an application server or stored by this form. Closing the form or refreshing the page clears the entries. Downloaded files remain on your device.</p><h3 class="modal-subtitle">Site services</h3><p>This version adds no marketing analytics or tracking cookies. Hosting services may process technical request information. Fonts load from Google Fonts, which receives normal network-request information. Access may require the hosting platform’s sign-in.</p><h3 class="modal-subtitle">Before commercial launch</h3><p>A confirmed company identity, contact channel, final product terms, data-source permissions, privacy and rights-request procedures, and fulfillment arrangements must be in place before real customer data or payments are accepted.</p>`);}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-detail'))detail(b.dataset.detail);else if(b.hasAttribute('data-sample'))sample(b.dataset.sample);else if(b.hasAttribute('data-download'))downloadSample(b.dataset.download);else if(b.hasAttribute('data-build'))build(Number(b.dataset.index||0),b.dataset.tier||'Intelligence');else if(b.hasAttribute('data-policy'))policy();else if(b.hasAttribute('data-filter')){activeFilter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(el=>{const active=el===b;el.classList.toggle('active',active);el.setAttribute('aria-pressed',String(active));});renderCollections();}});
document.querySelector('#search')?.addEventListener('input',renderCollections);document.querySelector('#year').textContent=new Date().getFullYear();renderCollections();
if(catalogPage){const category=new URLSearchParams(location.search).get('category');if(category){const button=Array.from(document.querySelectorAll('[data-filter]')).find(el=>el.dataset.filter===category);if(button)button.click();}}
if(document.modelContext?.registerTool){const controller=new AbortController();const tool={name:'configure_research_brief',title:'Configure a Reachventory research brief',description:'Open the visible draft brief builder for a collection and package. Does not submit an inquiry, create an order, charge money or download a file.',inputSchema:{type:'object',properties:{collectionIndex:{type:'integer',minimum:0,maximum:collections.length-1},package:{type:'string',enum:Object.keys(tiers)}},required:['collectionIndex','package'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input.collectionIndex!=='number'||!Number.isInteger(input.collectionIndex)||typeof input.package!=='string'||!Object.hasOwn(tiers,input.package))throw Error('Invalid collection or package');const i=validIndex(input.collectionIndex);build(i,input.package);return {status:'draft_open',collection:collections[i].name,package:input.package,submitted:false};}};try{Promise.resolve(document.modelContext.registerTool(tool,{signal:controller.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>controller.abort(),{once:true});}
